    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 d1, uint256 d2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d1) + (d2)); require(d1 <= 1000000000000000000000000000000); require(d2 <= 1000000000000000000000000000000);
        require(d1 > 0 && d2 > 0);
        require(address(this).balance >= d1 + d2);
        c.deposit{value: d1}(); if (__ESBMC_reverted()) return;
        c.deposit{value: d2}(); if (__ESBMC_reverted()) return;
        uint256 balBefore = address(this).balance;
        bool reverted;
        c.withdraw(d1 + d2); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
